			description: "Quantity 9 (no discount)",
			price:       10.0,
			quantity:    9,
			expected:    90.0,
		},
		{
			description: "Quantity 10 (10% discount boundary)",
			price:       10.0,
			quantity:    10,
			expected:    90.0, // 10 * 10 * 0.9 = 90
		},
		{
			description: "Quantity 49 (10% discount boundary)",
			price:       10.0,
			quantity:    49,
