import (
	"fmt"
	"os"
	"strconv"
)

func main() {
	// Check if the user provided at least one argument
	if len(os.Args) < 2 {
		return
	}

	// Parse the command line argument to an integer
	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		// If the argument is not a valid integer, we exit silently or could print an error
		return
	}

	// Prime numbers start from 2. If N < 2, there are no primes to print.
	if n < 2 {
		return
	}

	// Use the Sieve of Eratosthenes to find all primes up to N
	// Create a boolean slice "isPrime[0..n]" and initialize
	// all entries it as true. A value in isPrime[i] will
	// finally be false if i is Not a prime, else true.
	isPrime := make([]bool, n+1)
	for i := 2; i <= n; i++ {
		isPrime[i] = true
	}

	for p := 2; p*p <= n; p++ {
		// If isPrime[p] is not changed, then it is a prime
		if isPrime[p] == true {
			// Update all multiples of p starting from p*p
			// Multiples less than p*p would have already been marked
			for i := p * p; i <= n; i += p {
				isPrime[i] = false
			}
		}
	}

	// Print all prime numbers
	for p := 2; p <= n; p++ {
		if isPrime[p] {
			fmt.Println(p)
		}
	}
}
